UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"LP Approach Selection","body":"**Choose your approach:** [1][2][12]\n\n**MIDLINE Approach:**\n• Standard technique\n• Needle through interspinous ligaments\n• Requires good spine flexion\n\n**PARAMEDIAN Approach:**\n• **30-40% higher first-attempt success** than midline\n• Avoids supraspinous/interspinous ligaments\n• Does NOT require full spine flexion\n• Better for: elderly (calcified ligaments), kyphosis/scoliosis, failed midline\n• Lower PDPH incidence\n\n**Consider PARAMEDIAN if:**\n• Failed midline attempts\n• Calcified ligaments (age >50)\n• Severe degenerative changes\n• Cannot flex spine adequately\n• Kyphosis or scoliosis\n\nWhich approach will you use?","options":[{"label":"Midline approach","description":"Standard technique — through interspinous space","next":"lp-midline-start"},{"label":"Paramedian approach","description":"30-40% higher success — avoids ligaments. Opens 3-step visual guide.","next":"lp-paramedian-steps"}],"summary":"Midline approach is standard; paramedian for elderly or difficult anatomy (calcified ligaments)"}'::jsonb
